use std::fs

fn is_int(t: string) -> bool {
    let cs: Vec<char> = t.chars().collect()
    let n = cs.len()
    let start = if n > 0 && cs[0] == '-' { 1 } else { 0 }
    if n - start < 1 {
        return false
    }
    let mut i = start
    while i < n {
        if !cs[i].is_ascii_digit() {
            return false
        }
        i += 1
    }
    true
}

fn eval(line: string) -> string {
    let mut st: Vec<int> = []
    for t in line.split_whitespace() {
        if t == "+" || t == "-" || t == "*" || t == "/" {
            let n = st.len()
            if n < 2 {
                return "error: underflow"
            }
            let b = st[n - 1]
            let a = st[n - 2]
            if t == "/" && b == 0 {
                return "error: divzero"
            }
            st.pop()
            st.pop()
            let r = if t == "+" { a + b } else if t == "-" { a - b } else if t == "*" { a * b } else { a / b }
            st.push(r)
        } else if is_int(t) {
            st.push(t.parse::<int>().unwrap_or(0))
        } else {
            return "error: token"
        }
    }
    if st.len() != 1 {
        return "error: leftover"
    }
    "${st[0]}"
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim().is_empty() {
            continue
        }
        println(eval(line))
    }
}

